199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Pet pet = petMapper.toPet(petFieldsDto);
204	        owner.setId(ownerId);
205	        pet.setOwner(owner);
206	        pet.getType().setName(null);
207	        this.clinicService.savePet(pet);
208	        PetDto petDto = petMapper.toPetDto(pet);
209	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
210	            .buildAndExpand(pet.getId()).toUri());
211	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
212	    }
